#!/usr/bin/env bash
# Question 4: PersistentVolumeClaim ${Q4_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q4_NAME}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q4_NAME}
    type: DirectoryOrCreate
EOF
kubectl patch pv "${Q4_NAME}-pv" -p '{"spec": {"capacity": {"storage": "2Gi"}}}'
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q4_NAME}-pv-old
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q4_NAME}-old
    type: DirectoryOrCreate
EOF
